using Fugue.Domain.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Fugue.Infrastructure.Persistence.Configurations;

// UAM v3 port (docs/plans/s3-identity.md section 4). Ids are generated by the domain (UUIDv7); audit columns are
// stamped by AuditableSaveChangesInterceptor; typed ids convert by convention.

internal static class IdentityMapping
{
    public static void Audit<T>(EntityTypeBuilder<T> b) where T : class, Fugue.Domain.Abstractions.IAuditable
    {
        b.Property(e => e.CreatedBy).HasMaxLength(64).IsRequired();
        b.Property(e => e.UpdatedBy).HasMaxLength(64).IsRequired();
    }

    public static void Soft<T>(EntityTypeBuilder<T> b) where T : class, Fugue.Domain.Abstractions.ISoftDeletable
    {
        b.Property(e => e.DeletedBy).HasMaxLength(64);
    }
}

internal sealed class TenantConfiguration : IEntityTypeConfiguration<Tenant>
{
    public void Configure(EntityTypeBuilder<Tenant> b)
    {
        b.ToTable("tenants");
        b.HasKey(e => e.Id);
        b.Property(e => e.Id).ValueGeneratedNever();
        b.Property(e => e.Code).HasMaxLength(64).IsRequired();
        b.Property(e => e.Name).HasMaxLength(200).IsRequired();
        b.HasIndex(e => e.Code).IsUnique().HasDatabaseName("ux_tenants_code");
        IdentityMapping.Audit(b);
    }
}

internal sealed class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> b)
    {
        b.ToTable("users");
        b.HasKey(e => e.Id);
        b.Property(e => e.Id).ValueGeneratedNever();
        b.Property(e => e.DisplayName).HasMaxLength(200).IsRequired();
        b.Property(e => e.Email).HasMaxLength(254).IsRequired();
        b.Property(e => e.ContactNumber).HasMaxLength(32);
        b.Property(e => e.PasswordHash).HasMaxLength(512).IsRequired();
        // One canonical email key, unique among live rows only, so a deleted address can be reused.
        b.HasIndex(e => e.Email).IsUnique().HasFilter("NOT is_deleted").HasDatabaseName("ux_users_email_active");
        b.HasOne<Tenant>().WithMany().HasForeignKey(e => e.TenantId).OnDelete(DeleteBehavior.Restrict);
        b.HasIndex(e => e.TenantId).HasDatabaseName("ix_users_tenant_id");
        IdentityMapping.Audit(b);
        IdentityMapping.Soft(b);
    }
}

